<style scoped lang="scss" src="./report-filters.scss"></style>

<script>
import deepClone from "lodash/cloneDeep";
import { Component, Prop, Vue, Watch } from "vue-property-decorator";
import Select from "../select/select.vue";
import Button from "../button/button";
import { ButtonMode } from "../button/button.constants";
import { FilterType } from "../gms-new-report-modal/gms-new-report-modal.constants";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import SelectionMenu from "../selection-menu/selection-menu";
import { SelectionMenuMode } from "../selection-menu/selection-menu.constants";

@Component({
  components: {
    Button,
    Icon,
    SelectionMenu,
    Select,
  },
})
export default class ReportFilters extends Vue {
  @Prop({
    type: Array,
  })
  initialFilters;

  /**
   * Configure the dropdowns for the filters the user can add.
   * You configure the first column to be the filter types, then you add
   * configurations available for each filter type.
   *
   * {
   *   types: [
   *    {
   *      label: string,
   *      value: FilterType (DATE, STRING, NUMBER, DROPDOWN, MULTI_SELECT, UUID, NONE)
   *    },
   *    {
   *      label: string,
   *      value: FilterType
   *    },
   *    ...
   *   ],
   *   config: {
   *     // Key matches a value found in "types"
   *     value: [
   *       // Supports two dropdown configurations for the next two selections
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *     ],
   *
   *     // Key matches a value found in "types"
   *     value: [
   *       // Supports two dropdown configurations for the next two selections
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *     ],
   *
   *     // repeat for each value present in "types"
   *   }
   * }
   */
  @Prop({
    type: Object,
    default: () => ({
      types: [],
      config: {},
    }),
  })
  filterConfig;

  /**
   * Stores our filter data
   * { type: FilterType, value1: any, value2: any }[]
   */
  filters = [];

  // Constants
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  SelectionMenuMode = SelectionMenuMode;

  mounted() {
    this.filters = deepClone(this.initialFilters);
  }

  // Emit 'onFiltersChanged' event every time the filters are modified
  @Watch("filters", { deep: true })
  onFiltersChanged(filters) {
    this.$emit("onFiltersChanged", filters);
  }

  getFilterValues(filterIndex, configIndex) {
    const filter = this.filters[filterIndex];
    const config = this.filterConfig.config[filter.header_ref];

    if (config) {
      const configColumn = config[configIndex];

      if (configColumn) {
        return configColumn.options || [];
      }
    }

    return [];
  }

  getFilterPlaceholder(filterIndex, configIndex) {
    const filter = this.filters[filterIndex];
    const config = this.filterConfig.config[filter.header_ref];

    if (config) {
      const configColumn = config[configIndex];

      if (configColumn) {
        return configColumn.placeholder || undefined;
      }
    }

    return undefined;
  }

  isNumber(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.NUMBER;
  }

  isString(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.STRING || type === FilterType.UUID;
  }

  isDate(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.DATE;
  }

  isDropdown(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.DROPDOWN;
  }

  isMultiSelect(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.MULTI_SELECT;
  }

  /**
   * Handlers
   */

  handleDelete(index) {
    this.filters.splice(index, 1);
  }

  handleAddFilter() {
    this.filters.push({
      type: this.filterConfig.types[0].type,
      header_ref: this.filterConfig.types[0].header_ref,
      condition: {
        label: undefined,
        func: undefined,
      },
      filterValue: undefined,
    });
  }

  handleClearFilters() {
    this.filters = [];
  }

  handleFilterTypeChange(index, value, item) {
    const toChange = this.filters[index];
    /**
     * If changing from a string type to a number type, or if changing to a
     * multiselect dropdown, clear the value if the string is not a valid
     * number.
     */
    if (
      toChange.type === "string" &&
      item.type === "number" &&
      Number.isNaN(toChange.filterValue)
    ) {
      toChange.filterValue = undefined;
    }

    /**
     * it changing to a multi_select or a dropdown,set initial values correctly
     */
    if (item.type === "multi_select" || item.type === "dropdown") {
      if (!toChange.filterValue) {
        // if we don't have a value, set to the default value
        toChange.filterValue = this.getDefaultValue(item);
      } else {
        // if we have a value but it doesn't exist in the filter config, set with the default value.
        const options = this.filterConfig.config[item.header_ref]?.[1].options;
        if (typeof toChange.filterValue === "string") {
          toChange.filterValue = this.getDefaultValue(item);
        } else {
          const firstValue = toChange.filterValue[0];
          if (!options.map(o => o.value).includes(firstValue)) {
            toChange.filterValue = this.getDefaultValue(item);
          }
        }
      }
    }

    toChange.type = item.type;
    toChange.header_ref = item.header_ref;
    // initialize condition values when changing filter type
    toChange.condition = {
      ...this.filterConfig.config[item.header_ref]?.[0]?.options?.[0],
    };

    this.$forceUpdate();
  }

  handleConditionChange(index, value, condition) {
    this.filters[index].condition.label = value;
    this.filters[index].condition.func = condition.func;
    this.filters[index].condition.type = condition.type;
    this.$forceUpdate();
  }

  handleStringInput(e, index) {
    this.filters[index].filterValue = e.target.value;
  }

  handleNumberInput(e, index) {
    this.filters[index].filterValue = e.target.value;
  }

  handleDatePick(e, index) {
    this.filters[index].filterValue = e.target.value;
  }

  handleSelectOption(index, value) {
    this.filters[index].filterValue = value;
  }

  handleSelectionMultiOptions(index, values) {
    this.filters[index].filterValue = values;
  }

  getDefaultValue(item) {
    const defaultValue = this.filterConfig.config[item.header_ref]?.[1]
      .options?.[0]?.value;
    return item.type === "multi_select" ? [defaultValue] : defaultValue;
  }

  getFilterKey(header_ref, i) {
    return `${header_ref}_ ${i}`;
  }

  /**
   * Based on the given filter, return the value of the corresponding Filter Type field
   *
   * @default string the first filter type in the list of filter types if none is supplied
   */
  getInitialFilterType(filter) {
    return (
      this.filterConfig.types.find((type) => type.value === filter.header_ref)
        ?.value || this.filterConfig.types[0].value
    );
  }

  /**
   * Based on the given filter, return the value of the corresponding Condition field
   *
   * @default string the first condition in the list of conditions is none is supplied
   */
  getInitialCondition(filter) {
    return (
      this.filterConfig.config[filter.header_ref]?.[0]?.options?.find(
        (option) => option.value === filter?.condition?.label
      )?.value ||
      this.filterConfig.config[filter.header_ref]?.[0]?.options[0]?.value
    );
  }
}
</script>

<template>
  <div class="ReportFilters">
    <div class="ReportFilters__Row" v-for="(filter, i) in filters" :key="i">
      <button
        class="ReportFilters__Row-Delete"
        @click="handleDelete(i)"
        aria-label="Delete Filter"
      >
        <Icon :shape="IconShape.CLOSE" :size="24" />
      </button>
      <div class="ReportFilters__Row-Title" v-if="i === 0">Where</div>
      <div class="ReportFilters__Row-Title" v-else>And</div>

      <!-- Filter Type -->
      <Select
        class="ReportFilters__Row-Menu"
        search
        :label="getInitialFilterType(filter)"
        :value="getInitialFilterType(filter)"
        :items="filterConfig.types"
        @select="(value, item) => handleFilterTypeChange(i, value, item)"
      />

      <!-- Filter Condition -->
      <Select
        class="ReportFilters__Row-Menu"
        search
        :key="getFilterKey(filter.header_ref, i)"
        :label="getFilterPlaceholder(i, 0)"
        :value="getInitialCondition(filter, i)"
        :items="getFilterValues(i, 0)"
        @select="
          (value, condition) => handleConditionChange(i, value, condition)
        "
      />

      <!-- Filter Value -->
      <input
        v-if="isString(i)"
        :value="filters[i].filterValue"
        class="ReportFilters__Row-Input"
        type="text"
        placeholder="Enter a value here"
        @input="handleStringInput($event, i)"
      />
      <input
        v-else-if="isNumber(i)"
        :value="filters[i].filterValue"
        class="ReportFilters__Row-Input"
        type="number"
        placeholder="Enter a value here"
        @input="handleNumberInput($event, i)"
      />
      <input
        v-else-if="isDate(i)"
        :value="filters[i].filterValue"
        class="ReportFilters__Row-Input ReportFilters__Row-Input--DatePicker"
        type="date"
        placeholder="Enter a value here"
        @change="handleDatePick($event, i)"
      />
      <Select
        v-else-if="isDropdown(i)"
        class="ReportFilters__Row-Dropdown"
        search
        :label="getFilterPlaceholder(i, 1)"
        :items="getFilterValues(i, 1)"
        :value="filters[i].filterValue"
        @select="(value) => handleSelectOption(i, value)"
      />
      <Select
        v-else-if="isMultiSelect(i)"
        class="ReportFilters__Row-Dropdown"
        search
        multiselect
        :label="getFilterPlaceholder(i, 1)"
        :items="getFilterValues(i, 1)"
        :value="filters[i].filterValue"
        @select="(values) => handleSelectionMultiOptions(i, values)"
      />
    </div>

    <div class="ReportFilters__Row">
      <div class="ReportFilters__ButtonContainer">
        <Button
          :mode="ButtonMode.GMS_ICON"
          :icon="IconShape.PLUS"
          @click="handleAddFilter"
        />
        <span>Add Filter</span>
      </div>
      <div v-if="filters.length > 0" class="ReportFilters__ButtonContainer">
        <Button
          :mode="ButtonMode.GMS_ICON"
          :icon="IconShape.CLOSE"
          :iconColor="'#2356f6'"
          @click="handleClearFilters"
        />
        <span>Clear All Filters</span>
      </div>
    </div>
  </div>
</template>
